    /// HomeKit's air quality (1 excellent to 5 poor) from a PM2.5 reading in µg/m³, by Govee's manual.
    static func airQuality(pm25: Double) -> Int {
        if pm25 <= 12 { return 1 }
        if pm25 <= 35 { return 2 }
        if pm25 <= 75 { return 3 }
        if pm25 <= 115 { return 4 }
        return 5
    }

    static func airQualityLabel(pm25: Double) -> String { airQualityLabels[airQuality(pm25: pm25)] ?? "unknown" }
